import {$,esc,icon,common,modal,toast,load,save} from './prototype-shared.js?v=ec100736812be7db';
import {getDocuments} from './document-store.js?v=ec100736812be7db';
common();
// Fictional local data only. No service account data or mutation endpoints.
let documents=getDocuments();
const metadata=d=>`<dl class="document-context"><div class="document-meta-line"><div class="document-company"><dt>기업명</dt><dd>${esc(d.company||'기업 미지정')}</dd></div><div><dt>직종</dt><dd>${esc(d.job||'직종 미지정')}</dd></div></div><div class="document-meta-line document-secondary"><div><dt>업종</dt><dd>${esc(d.industry||'업종 미지정')}</dd></div><div><dt>기업형태</dt><dd>${esc(d.companyType||'기업형태 미지정')}</dd></div></div></dl>`;
const card=d=>`<article class="my-document" data-document="${esc(d.id)}"><div class="document-topline"><span class="doc-badge ${d.state.includes('완료')?'complete':''}">${esc(d.state)}</span><details class="document-menu"><summary aria-label="${esc(d.title)} 메뉴">${icon('Ellipsis')}</summary><div><button data-action="copy">${icon('Copy')}복사</button><button data-action="delete">${icon('Trash2')}삭제</button></div></details></div><a class="document-open" href="/prototypes/${d.kind==='cover'?'coverletter-write':'resume-write'}.html?document=${encodeURIComponent(d.id)}" aria-label="${esc(d.title)} · 이어서 작성">${esc(d.title)}</a>${metadata(d)}<div class="document-card-actions"><time datetime="${d.date.replaceAll('.','-')}">${d.date}</time>${d.state==='임시저장'?'':`<button class="representative-action" data-action="representative" aria-pressed="${d.representative}">${icon(d.representative?'CircleCheck':'Circle')}${d.representative?'대표 문서':'대표 설정'}</button>`}</div></article>`;
function render(){for(const kind of ['cover','resume'])$('#'+kind+'-documents').innerHTML=documents.filter(d=>d.kind===kind).map(card).join('')||'<p class="empty-documents">저장된 문서가 없습니다.</p>';}
const persist=()=>save('mypage-documents',documents);
$('#mypage-content').addEventListener('click',e=>{const button=e.target.closest('[data-action]'),card=button?.closest('[data-document]');if(!card)return;const d=documents.find(x=>x.id===card.dataset.document);if(!d)return;switch(button.dataset.action){case 'copy':{const clone={...d,id:crypto.randomUUID(),title:d.title+' (복사)',representative:false};for(const key of ['info:','questions:','resume:']){const value=load(key+d.id,null);if(value){if(key!=='questions:')value.title=clone.title;save(key+clone.id,value);}}documents.splice(documents.indexOf(d)+1,0,clone);persist();render();document.querySelector(`[data-document="${clone.id}"] .document-open`).focus();toast('문서를 복사했습니다.');break;}case 'delete':modal('문서를 삭제할까요?',`<p>${esc(d.title)}</p><p>문서와 작성한 내용이 삭제됩니다.</p>`,()=>{documents=documents.filter(x=>x!==d);persist();render();$('#mypage-content').focus();toast('문서를 삭제했습니다.');});$('#dialog-confirm').textContent='삭제';break;case 'representative':documents.filter(x=>x.kind===d.kind).forEach(x=>x.representative=x===d);persist();render();document.querySelector(`[data-document="${d.id}"] .representative-action`).focus();toast('대표 문서를 설정했습니다.');break;}});
document.addEventListener('click',e=>{document.querySelectorAll('.document-menu[open]').forEach(menu=>{if(!menu.contains(e.target))menu.open=false;});});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.document-menu[open]').forEach(menu=>{menu.open=false;menu.querySelector('summary').focus();});});
$('#send-application').addEventListener('click',()=>{const chosen=documents.filter(d=>d.representative);modal('입사지원서 보내기',`<p>대표로 설정한 자기소개서와 이력서</p><ul>${chosen.map(d=>`<li>${esc(d.title)}</li>`).join('')||'<li>대표 문서가 없습니다.</li>'}</ul><label class="dialog-field">받는 사람 이메일<input type="email" placeholder="example@company.com" autocomplete="off"></label>`);});
$('#profile-edit').addEventListener('click',()=>{let selected=null;modal('프로필 사진 변경',`<label class="profile-file-label">${icon('ImagePlus')}사진 선택<input class="profile-file" id="profile-file" type="file" accept="image/png,image/jpeg"></label><p id="profile-file-status">JPG 또는 PNG · 최대 5MB</p>`,()=>{if(selected){$('#profile-image').src=selected;$('#profile-image').hidden=false;toast('프로필 사진을 변경했습니다.');}});$('#profile-file').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png'].includes(file.type)||file.size>5*1024*1024){selected=null;$('#profile-file-status').textContent='5MB 이하 JPG 또는 PNG를 선택해 주세요.';return;}const reader=new FileReader();reader.onload=()=>{selected=reader.result;$('#profile-file-status').textContent=file.name;};reader.readAsDataURL(file);});});
render();
window.addEventListener('pageshow',event=>{if(event.persisted){const focused=document.activeElement?.closest('[data-document]')?.dataset.document;documents=getDocuments();render();if(focused)document.querySelector(`[data-document="${CSS.escape(focused)}"] .document-open`)?.focus();}});
